(function(){
const $=id=>document.getElementById(id);let rows=[],controller=PLC.fresh(),projects=[],activeProject=null;
try{rows=JSON.parse(localStorage.getItem('plcquest.ladder.v1'))||[];projects=JSON.parse(localStorage.getItem('plcquest.projects.v1'))||[];if(!Array.isArray(rows))rows=[];if(!Array.isArray(projects))projects=[];}catch{rows=[];projects=[];}
const panel=document.createElement('details');panel.className='workshop';panel.id='ladderWorkshop';panel.innerHTML=`<summary>Build your own ladder program</summary><p>Build rungs and branches, then enable this program to control the sandbox. Every station needs a Q output. Separate lifts and gates also need UP and DOWN commands. Two named timers and two counters are available.</p><div class="workshopbar"><label><input type="checkbox" id="useLadder"> Use this program on my line</label><button id="addRung" class="quiet">Add rung</button></div><div id="freeRungs"></div><div id="ladderLive" class="rungtrace"></div><details><summary>Commissioning test</summary><p>Build a two-conveyor program with Start/Stop memory. Motor holds after Start is released. Stop clears the command. Belt 2 requires Motor and Ready. A blocked transfer stops Belt 2, then it resumes when clear. Use the test tags MOTOR and BELT2 for these outputs.</p><button id="commissionTest" class="primary">Run commissioning checks</button><p id="commissionResult" role="status"></p></details>`;
$('sbEditor').after(panel);
const lineIO=document.createElement('details');lineIO.className='diagnostics lineio';lineIO.innerHTML='<summary>Live line inputs and outputs</summary><p>Tap a station to find it on the conveyor and in your ladder.</p><div id="lineIOList" class="iolist"></div>';$('sbStats').after(lineIO);
const library=document.createElement('details');library.className='projectlibrary';library.innerHTML=`<summary>My saved systems</summary><p>Save several designs with their layouts and ladder programs. These projects are stored in this browser.</p><div class="workshopbar"><input id="projectName" maxlength="60" placeholder="Name this system" aria-label="Project name"><button id="saveProject" class="primary">Save new copy</button></div><div class="workshopbar"><select id="projectList" aria-label="Saved projects"></select><button id="loadProject" class="quiet">Open selected</button><button id="updateProject" class="quiet">Update selected</button></div><p id="projectStatus" role="status"></p>`;$('sbStats').before(library);
function tags(){const {config}=Sandbox.getState();return ['TRUE','RUN','READY','START','STOP','BLOCKED','RESET','MOTOR','BELT2','LAMP','MEM1','MEM2','T1_DONE','T2_DONE','T1_TIMING','T2_TIMING','C1_DONE','C2_DONE',...config.flatMap(c=>['S_'+c.id,'CLEAR_'+c.id,'LOCAL_'+c.id,'UPPER_'+c.id,'LOWER_'+c.id,'Q_'+c.id,'UP_'+c.id,'DOWN_'+c.id])];}
function targets(type){if(['TON','RTO'].includes(type))return ['T1','T2'];if(type==='CTU')return ['C1','C2'];if(type==='RES')return ['T1','T2','C1','C2'];return ['MOTOR','BELT2','LAMP','MEM1','MEM2',...Sandbox.getState().config.flatMap(c=>['Q_'+c.id,'UP_'+c.id,'DOWN_'+c.id])];}
function options(list,v){return list.map(t=>`<option value="${esc(t)}" ${t===v?'selected':''}>${esc(t)}</option>`).join('');}
function validRows(candidate){if(!Array.isArray(candidate)||candidate.length>32)throw Error('Use up to 32 rungs.');for(const r of candidate){if(!r||!['OTE','OTL','OTU','TON','RTO','CTU','RES'].includes(r.type)||!Array.isArray(r.groups)||r.groups.length>6||!r.groups.length||!Number.isFinite(r.preset)||r.preset<.1||r.preset>60||typeof r.target!=='string')throw Error('Invalid rung.');for(const g of r.groups)if(!Array.isArray(g)||!g.length||g.length>3||g.some(t=>typeof t!=='string'||!/^!?[A-Z][A-Z0-9_]*$/.test(t)))throw Error('Invalid contact.');}return candidate;}
try{validRows(rows);}catch{rows=[];}
function compile(programRows=rows){validRows(programRows);const program={},rungs=programRows.map((r,i)=>({groups:r.groups.map((g,j)=>g.map((t,k)=>{const id=`r${i}g${j}c${k}`;program[id]=t;return id;})),type:r.type,out:['TON','RTO','CTU','RES'].includes(r.type)?null:r.target,unit:['TON','RTO','CTU','RES'].includes(r.type)?r.target:undefined,preset:r.preset}));return {lesson:{rungs},program};}
function resetController(){controller=PLC.fresh();}
function scan(config,s,dt){const bits={RUN:s.run,START:s.run,STOP:!s.run,READY:s.ready,BLOCKED:config.some(c=>s.stations[c.id].fault),RESET:false};config.forEach((c,i)=>{const st=s.stations[c.id],next=LineSim.nextStation(config,s,i);Object.assign(bits,{['S_'+c.id]:!!st.box,['CLEAR_'+c.id]:!next||!s.stations[next.id].box,['LOCAL_'+c.id]:st.local,['UPPER_'+c.id]:st.position>=1,['LOWER_'+c.id]:st.position<=0});});const p=compile();PLC.scan(p.lesson,p.program,controller,bits,dt*1000);return controller.bits;}
function changed(){try{localStorage.setItem('plcquest.ladder.v1',JSON.stringify(rows));}catch{$('ladderLive').textContent='Could not save this ladder in browser storage.';}resetController();Sandbox.reset();render();}
function render(){const all=tags().flatMap(t=>t==='TRUE'?[t]:[t,'!'+t]);$('freeRungs').innerHTML=rows.length?rows.map((r,i)=>`<section class="freerung"><div class="freerunghead"><b>Rung ${i+1}</b><button data-action="remove" data-row="${i}" class="textbutton">Remove rung</button></div><div class="freecontacts">${r.groups.map((g,j)=>`<div class="freegroup">${g.map((t,k)=>`<div><select aria-label="Rung ${i+1} contact" data-row="${i}" data-group="${j}" data-contact="${k}">${options(all.includes(t)?all:[t,...all],t)}</select><button class="tiny" data-action="removeContact" data-row="${i}" data-group="${j}" data-contact="${k}" aria-label="Remove contact">×</button></div>`).join('')}<button class="tiny" data-action="parallel" data-row="${i}" data-group="${j}" ${g.length>=3?'disabled':''}>Add OR branch</button></div>`).join('<span class="andword">AND</span>')}<button class="quiet" data-action="series" data-row="${i}" ${r.groups.length>=6?'disabled':''}>Add series contact</button></div><div class="workshopbar"><label>Instruction <select data-row="${i}" data-field="type">${options(['OTE','OTL','OTU','TON','RTO','CTU','RES'],r.type)}</select></label><label>Target <select data-row="${i}" data-field="target">${options(targets(r.type).includes(r.target)?targets(r.type):[r.target,...targets(r.type)],r.target)}</select></label>${['TON','RTO','CTU'].includes(r.type)?`<label>Preset <input type="number" min="0.1" max="60" step="0.1" value="${r.preset}" data-row="${i}" data-field="preset"></label>`:''}</div></section>`).join(''):'<p class="helper">No rungs yet. Add one, choose contacts, and choose the output it controls. ! means check for OFF. TRUE is an unconditional path.</p>';$('addRung').disabled=rows.length>=32;live();}
function live(){if(!$('ladderLive'))return;const {state,config}=Sandbox.getState();$('lineIOList').innerHTML=config.map(c=>{const st=state.stations[c.id];return `<button class="iotag" data-findstation="${c.id}"><span>${c.id} · ${LineSim.titles[c.type]}<small>S_${c.id}: ${st.box?1:0} · Q_${c.id}: ${st.output?1:0}${['lift','stop'].includes(c.type)?` · Upper/extended: ${st.position>=1?1:0} · Lower/retracted: ${st.position<=0?1:0}`:''}</small></span></button>`;}).join('');const text=state.externalPLC?`Program scan ${controller.scans}. `+Object.entries(controller.bits).filter(([k,v])=>v&&(k.startsWith('Q_')||k.startsWith('UP_')||k.startsWith('DOWN_')||['MOTOR','BELT2'].includes(k))).map(([k])=>k+' ON').join(' · '):'Station controls are active. Check “Use this program on my line” to let these rungs drive the outputs.';$('ladderLive').textContent=text;}
function stationPanel(c,st){if(!c||!['lift','stop'].includes(c.type))return;const block=document.createElement('div');block.className='actuatorpanel';const up=c.type==='lift'?'Up':'Extend',down=c.type==='lift'?'Down':'Retract',localTags=['LOCAL','!LOCAL','RUN','!RUN','READY','!READY','OCCUPIED','!OCCUPIED','UPPER','!UPPER','LOWER','!LOWER','EXTENDED','!EXTENDED','RETRACTED','!RETRACTED','TRUE'];block.innerHTML=`<label>Actuator control <select id="actuatorMode"><option value="auto" ${c.control!=='separate'?'selected':''}>Automatic training cycle</option><option value="separate" ${c.control==='separate'?'selected':''}>Separate motion commands</option></select></label>${c.control==='separate'?`<p>Position feedback stops each direction at its limit. Opposing commands together hold the actuator and report a conflict. A loaded lift must reach upper, then return to lower before transfer.</p>${[['upA','upB',up,'LOCAL',c.type==='lift'?'!UPPER':'!EXTENDED'],['downA','downB',down,'!LOCAL',c.type==='lift'?'!LOWER':'!RETRACTED']].map(([a,b,label,da,db])=>`<div class="workshopbar"><b>${label}</b><select data-motion="${a}">${options(localTags,c[a]||da)}</select><span>AND</span><select data-motion="${b}">${options(localTags,c[b]||db)}</select></div>`).join('')}<p>Use the station’s Local switch to try the default motion commands. The ladder editor overrides these rules when enabled.</p>`:''}`;$('sbEditor').append(block);$('actuatorMode').onchange=e=>Sandbox.updateStation(c.id,{control:e.target.value});block.onchange=e=>{if(e.target.dataset.motion)Sandbox.updateStation(c.id,{[e.target.dataset.motion]:e.target.value});};}
function projectOptions(){$('projectList').innerHTML=projects.length?projects.map((p,i)=>`<option value="${i}" ${i===activeProject?'selected':''}>${esc(p.name)}</option>`).join(''):'<option value="">No saved systems</option>';}
function snapshot(){const d=Sandbox.getState();return {name:$('projectName').value.trim()||'Conveyor system',config:JSON.parse(JSON.stringify(d.config)),layout:d.layout,rows:JSON.parse(JSON.stringify(rows))};}
function storeProjects(){try{localStorage.setItem('plcquest.projects.v1',JSON.stringify(projects));$('projectStatus').textContent='Saved in this browser.';projectOptions();}catch{$('projectStatus').textContent='Could not save. Browser storage may be full.';}}
$('saveProject').onclick=()=>{if(projects.length>=30){$('projectStatus').textContent='Up to 30 systems can be saved. Update a selected system.';return;}projects.push(snapshot());activeProject=projects.length-1;storeProjects();};$('updateProject').onclick=()=>{const i=Number($('projectList').value);if(!projects[i])return;projects[i]=snapshot();activeProject=i;storeProjects();};$('loadProject').onclick=()=>{const i=Number($('projectList').value),p=projects[i];if(!p)return;try{LineSim.validate(p.config);validRows(p.rows);rows=JSON.parse(JSON.stringify(p.rows));activeProject=i;$('projectName').value=p.name;$('useLadder').checked=false;Sandbox.loadDesign(p);changed();$('projectStatus').textContent='Opened '+p.name+'. Enable the ladder when ready.';}catch{$('projectStatus').textContent='This saved system could not be opened.';}};
$('addRung').onclick=()=>{if(rows.length>=32)return;rows.push({groups:[['RUN']],type:'OTE',target:'MOTOR',preset:1});changed();};$('useLadder').onchange=e=>{Sandbox.enablePLC(e.target.checked);};
$('freeRungs').onchange=e=>{const i=Number(e.target.dataset.row),r=rows[i];if(!r)return;if(e.target.dataset.field){const k=e.target.dataset.field;if(k==='preset'){const v=Number(e.target.value);if(!Number.isFinite(v)||v<.1||v>60){render();return;}r[k]=v;}else r[k]=e.target.value;if(k==='type')r.target=targets(r.type)[0];}else r.groups[Number(e.target.dataset.group)][Number(e.target.dataset.contact)]=e.target.value;changed();};
$('freeRungs').onclick=e=>{const b=e.target.closest('[data-action]');if(!b)return;const i=Number(b.dataset.row),r=rows[i],g=Number(b.dataset.group);if(!r)return;if(b.dataset.action==='remove')rows.splice(i,1);if(b.dataset.action==='series'&&r.groups.length<6)r.groups.push(['RUN']);if(b.dataset.action==='parallel'&&r.groups[g].length<3)r.groups[g].push('RUN');if(b.dataset.action==='removeContact'){r.groups[g].splice(Number(b.dataset.contact),1);if(!r.groups[g].length)r.groups.splice(g,1);if(!r.groups.length)r.groups=[['TRUE']];}changed();};
function commissioning(){const p=compile(),reference={rungs:[{groups:[['a','b'],['c']],type:'OTE',out:'MOTOR'},{groups:[['d'],['e'],['f']],type:'OTE',out:'BELT2'}]},answer={a:'START',b:'MOTOR',c:'!STOP',d:'MOTOR',e:'READY',f:'!BLOCKED'};const tests=[{name:'Start and holding',steps:[{START:true,READY:true},{READY:true},{READY:true}]},{name:'Stop priority and no automatic restart',steps:[{START:true,READY:true},{START:true,STOP:true,READY:true},{READY:true}]},{name:'Blocked transfer and recovery',steps:[{START:true,READY:true},{READY:true,BLOCKED:true},{READY:true}]},{name:'Downstream permission',steps:[{START:true},{READY:true},{READY:false}]}];let checks=0;for(const t of tests){const actual=PLC.fresh(),expected=PLC.fresh();for(const input of t.steps)for(let i=0;i<3;i++){const bits={START:false,STOP:false,READY:false,BLOCKED:false,RUN:false,...input};PLC.scan(reference,answer,expected,bits);PLC.scan(p.lesson,p.program,actual,bits);checks++;for(const out of ['MOTOR','BELT2'])if(!!actual.bits[out]!==!!expected.bits[out])return {ok:false,message:`${t.name}: ${out} should be ${expected.bits[out]?'ON':'OFF'} at scan ${actual.scans}. Check the specification and retry.`};}}return {ok:true,message:`Commissioning passed: ${checks} scans across startup, holding, Stop priority, restart, blockage, and downstream permission. This is a training check, not a machine safety validation.`};}
$('commissionTest').onclick=()=>{Sandbox.pause();const r=commissioning();$('commissionResult').textContent=r.message;$('commissionTest').textContent=r.ok?'Commissioning passed':'Try commissioning again';};
$('lineIOList').onclick=e=>{const b=e.target.closest('[data-findstation]');if(!b)return;const id=b.dataset.findstation;Sandbox.select(id);for(const [i,el] of [...document.querySelectorAll('.freerung')].entries())el.classList.toggle('tagfocus',rows[i].target.endsWith('_'+id)||rows[i].groups.flat().some(t=>t.endsWith('_'+id)));};
window.LineController={scan};window.Workshop={render,live,stationPanel,resetController,compile,commissioning,getRows:()=>JSON.parse(JSON.stringify(rows)),setRows:v=>{rows=validRows(JSON.parse(JSON.stringify(v)));changed();}};projectOptions();render();Sandbox.render();
})();
